//! 🎟️ Defining accepted semantic tree alias admission and return conserve the same original caller without copying owner storage.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation};
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress};
use semio_framework_test_fixtures::fixture_text;
fn clock()->Option<u64>{Some(1000)}
fn observed<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn original_presented_tree_alias_same_caller_denials_no_owner_copy_and_paid_return(){
 let policy:serde_json::Value=serde_json::from_str(fixture_text!("../../../../../../../../../🛍️products/💻️os/🔨️modules/🔌️plugin/🧪️testing/🎟️caller/🧪️tests/🧫️fixtures/🎟️caller.json")).unwrap();let stock:RetainedCloneGrant=serde_json::from_value(policy["grant"].clone()).unwrap();let mut ui=Ui::new(semio_framework_ui_locale::Locale::En);let surface=ui.windows.try_admit(SurfaceId::try_from("accepted-window").unwrap()).unwrap();{let window=ui.windows.get_token_mut(surface).unwrap();window.presented_ready=true;window.presented_revision=71;window.presented_accessibility_generation=19;}let pointer=&ui.windows.get_token(surface).unwrap().presented_tree as*const UiTree;
 let(mut caller,born)=observed(||OriginalJobFixtureCaller::admit(OperationId(policy["operation"].as_u64().unwrap()),Generation(policy["generation"].as_u64().unwrap()),stock,clock,policy["deadlineUs"].as_u64().unwrap(),policy["fuel"].as_u64().unwrap()));caller.turn(stock,|cx|{let identity=(cx.operation(),cx.generation(),cx.deadline_us(),cx.clock_source()as usize,cx.original_recipient_identity());let before=cx.retained_progress();let fuel=cx.fuel_remaining();let(result,heap)=observed(||cx.with_retained_loan(RetainedCloneGrant{maximum_items:0,..stock},|same|{assert!(ui.admit_presented_tree_source(surface,same)?.is_none());Ok(())}));result?;assert_eq!(heap,(0,0));assert_eq!(before,cx.retained_progress());assert_eq!(fuel,cx.fuel_remaining());
  let(result,heap)=observed(||ui.admit_presented_tree_source(surface,cx));let mut loan=result?.unwrap();assert_eq!(heap,(0,0));assert_eq!(cx.retained_progress(),before.checked_add(RetainedCloneProgress{copied_items:1,..Default::default()})?);assert_eq!(ui.original_presented_tree_source(&loan).unwrap()as*const UiTree,pointer);assert!(!ui.windows.get_token_mut(surface).unwrap().close_presented_tree_storage_step("accepted-window"));let before=cx.retained_progress();let fuel=cx.fuel_remaining();let(result,heap)=observed(||ui.admit_presented_tree_source(surface,cx));assert!(result?.is_none());assert_eq!(heap,(0,0));assert_eq!(before,cx.retained_progress());assert_eq!(fuel,cx.fuel_remaining());
  let(result,heap)=observed(||cx.with_retained_loan(RetainedCloneGrant{maximum_depth:0,..stock},|same|{assert!(!ui.return_presented_tree_source(&mut loan,same)?);Ok(())}));result?;assert_eq!(heap,(0,0));assert_eq!(before,cx.retained_progress());assert_eq!(ui.original_presented_tree_source(&loan).unwrap()as*const UiTree,pointer);
  ui.windows.get_token_mut(surface).unwrap().advance_presented_interaction();assert!(ui.original_presented_tree_source(&loan).is_none());assert!(!ui.windows.get_token_mut(surface).unwrap().close_presented_tree_storage_step("accepted-window"));let(result,heap)=observed(||ui.return_presented_tree_source(&mut loan,cx));assert!(result?);assert_eq!(heap,(0,0));assert_eq!(cx.retained_progress(),before.checked_add(RetainedCloneProgress{copied_items:1,..Default::default()})?);assert_eq!(cx.fuel_remaining(),fuel-1);assert!(ui.windows.get_token(surface).unwrap().presented_source.is_none());assert_eq!(observed(||drop(loan)).1,(0,0));assert_eq!((cx.operation(),cx.generation(),cx.deadline_us(),cx.clock_source()as usize,cx.original_recipient_identity()),identity);Ok(())}).unwrap();let(_,freed)=observed(||caller.retire(stock));assert_eq!(born.0+freed.0,born.1+freed.1);
}
